<?php require_once __DIR__.'/includes/bootstrap.php';require_admin();$notice='';if(is_post()){verify_csrf();$id=(int)$_POST['id'];$status=$_POST['status']??'pending';if($db&&in_array($status,['pending','approved','rejected'],true)){try{$db->beginTransaction();$st=$db->prepare('SELECT * FROM fund_requests WHERE id=? FOR UPDATE');$st->execute([$id]);$r=$st->fetch();if($r&&$r['status']==='pending'){$db->prepare('UPDATE fund_requests SET status=? WHERE id=?')->execute([$status,$id]);if($status==='approved'){$db->prepare('UPDATE users SET account_balance=account_balance+? WHERE id=?')->execute([$r['amount'],$r['user_id']]);$db->prepare('INSERT INTO balance_transactions(user_id,type,amount,reference,status) VALUES(?,?,?,?,?)')->execute([$r['user_id'],'fund_added',$r['amount'],'Fund Request #'.$id,'approved']);$us=$db->prepare('SELECT * FROM users WHERE id=?');$us->execute([$r['user_id']]);if($uu=$us->fetch())wdh_customer_message($db,$uu,'Account balance updated','Your fund request #'.$id.' for '.money($r['amount'],'BDT').' has been approved and added to your WDH account balance.','balance.php','fund_approved');} elseif($status==='rejected'){ $us=$db->prepare('SELECT * FROM users WHERE id=?');$us->execute([$r['user_id']]);if($uu=$us->fetch())wdh_customer_message($db,$uu,'Fund request update','Your fund request #'.$id.' was not approved. Please review your payment details or contact support.','balance.php','fund_rejected'); }}$db->commit();$notice='Fund request updated.';}catch(Throwable $e){if($db->inTransaction())$db->rollBack();$notice='Unable to update request.';}}}$rows=$db?$db->query('SELECT f.*,u.full_name,u.email FROM fund_requests f LEFT JOIN users u ON u.id=f.user_id ORDER BY f.id DESC')->fetchAll():[];?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin Balance</title><link rel="stylesheet" href="assets/css/style.css?v=wdh-ui-v8"><link rel="stylesheet" href="assets/css/catalog.css?v=wdh-ui-v8"></head><body><?php require __DIR__.'/includes/header.php';?><main class="admin-page"><div class="portal-welcome"><div><span class="eyebrow mint">ADMIN</span><h1>Fund Requests</h1><p>Approve customer account balance additions.</p></div></div><?php if($notice):?><div class="alert success-alert"><?=e($notice)?></div><?php endif;?><div class="admin-table"><?php foreach($rows as $r):?><form method="post" class="admin-row"><?=csrf_field()?><input type="hidden" name="id" value="<?=$r['id']?>"><div><strong><?=e($r['full_name']??'')?></strong><small><?=e($r['email']??'')?> · <?=e($r['method'])?></small></div><strong><?=money($r['amount'],'BDT')?></strong><small><?=e($r['transaction_id']??'')?> <?=e($r['sender_number']??'')?></small><select name="status"><option <?=$r['status']==='pending'?'selected':''?>>pending</option><option <?=$r['status']==='approved'?'selected':''?>>approved</option><option <?=$r['status']==='rejected'?'selected':''?>>rejected</option></select><button class="btn primary small">Update</button></form><?php endforeach;?></div></main><?php require __DIR__.'/includes/footer.php';?></body></html>
